import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("[127.0.0.1](http://127.0.0.1:8000/data)");
      setData(res.data);
      setLoading(false);
    } catch (err) {
      console.log("ERROR API:", err);
      setLoading(false);
    }
  };

  const latest = data.length > 0 ? data[0] : {};

  useEffect(() => {
    if (page === "monitoring") startCamera();
  }, [page]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch {
      alert("Izinkan kamera terlebih dahulu!");
    }
  };

  const sendFrame = async () => {
    if (!videoRef.current) return;

    const tempCanvas = document.createElement("canvas");
    tempCanvas.width = 640;
    tempCanvas.height = 480;
    const ctx = tempCanvas.getContext("2d");
    ctx.drawImage(videoRef.current, 0, 0, 640, 480);

    const blob = await new Promise(resolve =>
      tempCanvas.toBlob(resolve, "image/jpeg")
    );

    const formData = new FormData();
    formData.append("file", blob, "frame.jpg");

    try {
      const res = await axios.post("[127.0.0.1](http://127.0.0.1:8000/detect)", formData);
      drawBoxes(res.data.boxes || []);
    } catch (err) {
      console.log("ERROR DETECT:", err);
    }
  };

  useEffect(() => {
    if (page !== "monitoring") return;
    const interval = setInterval(sendFrame, 1500);
    return () => clearInterval(interval);
  }, [page]);

  const drawBoxes = (boxes) => {
    if (!canvasRef.current) return;
    const ctx = canvasRef.current.getContext("2d");
    ctx.clearRect(0, 0, 640, 480);
    ctx.strokeStyle = "lime";
    ctx.lineWidth = 3;
    boxes.forEach(box => {
      ctx.strokeRect(box.x1, box.y1, box.x2 - box.x1, box.y2 - box.y1);
    });
  };

  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e",
        backgroundColor: "rgba(34,197,94,0.2)",
        tension: 0.3,
      },
    ],
  };

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f97316";
    return "#22c55e";
  };

  const NavItem = ({ title, name }) => (
    <p
      onClick={() => setPage(name)}
      style={{
        margin: "10px 0",
        padding: 10,
        borderRadius: 8,
        background: page === name ? "#334155" : "transparent",
        cursor: "pointer",
        color: page === name ? "#22c55e" : "white"
      }}
    >
      {title}
    </p>
  );

  return (
    <div style={{ display: "flex", background: "#0f172a", color: "white", minHeight: "100vh" }}>

      {/* Sidebar */}
      <div style={{ width: 240, background: "#1e293b", padding: 20 }}>
        <h2 style={{ fontSize: 26, marginBottom: 20 }}>⚡ Hematrik</h2>
        <NavItem title="📊 Dashboard" name="dashboard" />
        <NavItem title="📷 Monitoring" name="monitoring" />
        <NavItem title="📜 History" name="history" />
      </div>

      {/* Main */}
      <div style={{ flex: 1, padding: 30 }}>
        {loading && <h2>Loading data...</h2>}

        {/* DASHBOARD */}
        {page === "dashboard" && data.length > 0 && (
          <>
            <h1 style={{ fontSize: 28 }}>📈 Dashboard Monitoring</h1>

            <div style={{
              padding: 16,
              borderRadius: 10,
              background: getColor(latest.kondisi),
              fontWeight: "bold",
              marginTop: 15
            }}>
              {latest.notifikasi}
            </div>

            <div style={{ display: "flex", gap: 20, marginTop: 25 }}>
              <div style={card}><h3>👥 Orang</h3><h1>{latest.jumlah_orang}</h1></div>
              <div style={card}><h3>🔌 Listrik</h3><h1>{latest.status_listrik}</h1></div>
              <div style={card}><h3>📟 Kondisi</h3>
                <h1 style={{ color: getColor(latest.kondisi) }}>{latest.kondisi}</h1>
              </div>
            </div>

            <div style={{ marginTop: 40 }}>
              <Line data={chartData} />
            </div>
          </>
        )}

        {/* MONITORING */}
        {page === "monitoring" && (
          <>
            <h1 style={{ fontSize: 28 }}>📷 Live CCTV AI</h1>
            <div style={{ position: "relative", width: 640, marginTop: 20 }}>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                style={{
                  width: "640px",
                  height: "480px",
                  borderRadius: 10,
                  objectFit: "cover",
                  background: "#000"
                }}
              />
              <canvas
                ref={canvasRef}
                width={640}
                height={480}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  borderRadius: 10
                }}
              />
            </div>
            <p style={{ marginTop: 10, color: "#94a3b8" }}>📡 AI mendeteksi orang setiap 1,5 detik</p>
          </>
        )}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1 style={{ fontSize: 28 }}>📜 History Monitoring</h1>
            <table style={{
              width: "100%",
              marginTop: 20,
              borderCollapse: "collapse"
            }}>
              <thead style={{ background: "#1e293b" }}>
                <tr>
                  {["Waktu", "Orang", "Listrik", "Kondisi"].map(h => (
                    <th key={h} style={{ padding: "10px 12px", textAlign: "left" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.map(d => (
                  <tr key={d.id} style={{ borderBottom: "1px solid #334155" }}>
                    <td style={{ padding: 10 }}>{d.waktu}</td>
                    <td style={{ padding: 10 }}>{d.jumlah_orang}</td>
                    <td style={{ padding: 10 }}>{d.status_listrik}</td>
                    <td style={{ padding: 10, color: getColor(d.kondisi) }}>{d.kondisi}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}
      </div>
    </div>
  );
}

const card = {
  background: "#1e293b",
  padding: 20,
  borderRadius: 10,
  width: 180,
  textAlign: "center",
};

export default App;
